from pathlib import Path

import duckdb
import pytest
from fastapi.testclient import TestClient

import api.main as api


# =============================================================================
# Configuration
# =============================================================================

# Path to the synthetic DuckDB database generated by the POPGEN pipeline.
#
# Path(__file__) returns the absolute path of the current test file.
# parents[1] moves two directory levels up:
#   tests/test_api.py -> tests -> project root
#
# The database is expected to be located in the project's db/ directory.
#
# This database contains a small synthetic dataset (200 variants) specifically
# designed to test the API without requiring the full production database.
DB_PATH = Path(__file__).resolve().parents[1] / "db/snvindel.200variants.db"


# =============================================================================
# Pytest fixtures
# =============================================================================

@pytest.fixture
def client(monkeypatch):
    """
    Create a FastAPI TestClient connected to the synthetic test database.

    This fixture is automatically called by pytest whenever a test function
    declares 'client' as an argument.

    The fixture:
      1. Checks that the synthetic DuckDB database exists.
      2. Replaces the API database path with the test database path.
      3. Starts the FastAPI application using TestClient.
      4. Returns the test client to the test function.

    monkeypatch temporarily modifies api.DB_PATH.
    The original value is automatically restored after the test.

    TestClient also triggers the FastAPI application lifespan events,
    including startup validation and database initialization.

    The database is accessed in read-only mode by the API.
    """

    # Ensure that the synthetic database has been generated before running
    # the API tests.
    if not DB_PATH.is_file():
        pytest.fail(
            f"Test database not found: {DB_PATH}. "
            "Build the 200-variant test database first."
        )

    # Replace the production database path defined in api.main
    # with the synthetic database path used for testing.
    #
    # This prevents the tests from accessing or modifying the production DB.
    monkeypatch.setattr(api, "DB_PATH", DB_PATH)

    # Start the FastAPI application and expose its HTTP endpoints.
    #
    # The context manager ensures that the application is properly started
    # before the tests and shut down after the tests.
    with TestClient(api.app) as test_client:
        yield test_client


# =============================================================================
# Database helper functions
# =============================================================================

def get_db_value(query, params=()):
    """
    Execute a read-only SQL query against the synthetic DuckDB database.

    This helper is used to retrieve existing values directly from the
    database before testing the corresponding API filters.

    For example:
      - Retrieve an existing chromosome.
      - Retrieve an existing variant ID.
      - Retrieve an existing gene symbol.
      - Retrieve an existing consequence annotation.

    Args:
        query (str):
            SQL query to execute.
        params (tuple):
            Optional parameters passed to the SQL query.

    Returns:
        The first column of the first returned row.
        Returns None if the query does not return any row.

    The database is opened in read-only mode to prevent accidental changes
    to the synthetic test dataset.
    """

    # Open a temporary read-only connection to DuckDB.
    with duckdb.connect(str(DB_PATH), read_only=True) as con:

        # Execute the SQL query and retrieve the first matching row.
        row = con.execute(query, params).fetchone()

    # Return the first column of the result, or None if no row was found.
    return row[0] if row else None


# =============================================================================
# Health endpoint tests
# =============================================================================

def test_health(client):
    """
    Test the /health endpoint.

    This endpoint checks whether the API and its DuckDB database
    are available.

    Expected response:
      - HTTP status code: 200
      - API status: ok
      - Database status: ok
    """

    # Send an HTTP GET request to the health endpoint.
    response = client.get("/health")

    # Check that the request was successfully processed.
    assert response.status_code == 200

    # Check that both the API and the database report a healthy status.
    assert response.json() == {
        "status": "ok",
        "database": "ok",
    }


# =============================================================================
# Variant endpoint tests
# =============================================================================

def test_variants_return_expected_columns(client):
    """
    Test the basic structure of the /variants endpoint response.

    The API should return the eight requested variant-level fields:
      - chrom: chromosome
      - pos: genomic position
      - ref: reference allele
      - alt: alternate allele
      - id: variant identifier
      - af: allele frequency
      - ac: alternate allele count
      - an: total allele number

    The number of returned results must also be consistent with the
    count field and respect the requested pagination limit.
    """

    # Request up to 10 variants without applying any additional filters.
    response = client.get("/variants", params={"limit": 10})

    # Ensure that the API request was successful.
    assert response.status_code == 200

    # Convert the JSON response into a Python dictionary.
    data = response.json()

    # The count field must correspond to the actual number of returned rows.
    assert data["count"] == len(data["results"])

    # The API must never return more rows than the requested limit.
    assert data["count"] <= 10

    # The synthetic database should contain at least one matching variant.
    assert data["count"] > 0

    # Define the exact set of fields expected in each returned variant.
    expected_columns = {
        "chrom",
        "pos",
        "ref",
        "alt",
        "id",
        "af",
        "ac",
        "an",
    }

    # Verify that every returned variant contains exactly these fields.
    # This also ensures that unexpected internal annotation columns
    # are not exposed by the variant-level API response.
    for variant in data["results"]:
        assert set(variant.keys()) == expected_columns


def test_variants_are_deduplicated(client):
    """
    Test that the API removes duplicate variant records.

    The expected uniqueness criterion is the combination of:
      - chromosome
      - variant ID
      - genomic position
      - reference allele
      - alternate allele

    This is important because the underlying database can contain several
    annotation rows for the same variant due to VEP CSQ expansion.

    Different annotations must not cause the same variant to appear
    multiple times in the variant-level API response.

    The synthetic dataset is expected to contain exactly 200 unique variants.
    """

    # Request all variants from the synthetic dataset.
    # The limit of 500 is greater than the expected number of variants.
    response = client.get("/variants", params={"limit": 500})

    # Ensure that the API request was successful.
    assert response.status_code == 200

    # Extract the list of variants from the JSON response.
    results = response.json()["results"]

    # Build a composite key for each variant using the expected uniqueness
    # criterion: (chromosome, ID, position, reference allele, alternate allele).
    keys = [(v["chrom"], v["id"], v["pos"], v["ref"], v["alt"]) for v in results]

    # The number of keys must equal the number of unique keys.
    # If duplicates are present, this assertion will fail.
    assert len(keys) == len(set(keys))

    # Check that all 200 expected variants are returned.
    assert len(keys) == 200


# =============================================================================
# Coordinate filtering tests
# =============================================================================

def test_filter_by_coordinates(client):
    """
    Test filtering variants using chromosome and genomic coordinates.

    The API accepts:
      - chrom: chromosome name
      - start: minimum genomic position
      - end: maximum genomic position

    This test dynamically retrieves an existing chromosome and position
    from the database instead of relying on hardcoded test values.

    By setting start = end, the test requests variants at one exact position.
    """

    # Retrieve an existing chromosome from the synthetic database.
    sample = get_db_value("SELECT chrom FROM variants LIMIT 1")

    # Retrieve an existing genomic position on that chromosome.
    # Using an existing position guarantees that the test has a valid
    # coordinate to search for.
    position = get_db_value(
        "SELECT pos FROM variants WHERE chrom = ? LIMIT 1",
        (sample,),
    )

    # Request variants located at the selected chromosome and position.
    response = client.get(
        "/variants",
        params={
            "chrom": sample,
            "start": position,
            "end": position,
        },
    )

    # Ensure that the API request was successful.
    assert response.status_code == 200

    # Extract the matching variants.
    results = response.json()["results"]

    # At least one variant should exist at the selected position.
    assert results

    # Verify that all returned variants match the requested chromosome
    # and exact genomic position.
    for variant in results:
        assert variant["chrom"] == sample
        assert variant["pos"] == position


# =============================================================================
# Variant ID filtering tests
# =============================================================================

def test_filter_by_id(client):
    """
    Test filtering variants using their variant identifier.

    The test retrieves an existing usable ID directly from the database.

    Missing or placeholder IDs (NULL, empty strings or '.') are excluded
    because they cannot be used as meaningful variant identifiers.
    """

    # Retrieve an existing non-null and non-placeholder variant ID.
    variant_id = get_db_value("""
        SELECT id
        FROM variants
        WHERE id IS NOT NULL AND id != '' AND id != '.'
        LIMIT 1
    """)

    # Skip the test if no usable ID is available in the test database.
    # This avoids testing the API with an invalid or meaningless identifier.
    if variant_id is None:
        pytest.skip("No usable variant ID in the test database.")

    # Request variants matching the selected identifier.
    response = client.get("/variants", params={"id": variant_id})

    # Ensure that the API request was successful.
    assert response.status_code == 200

    # Extract the returned variants.
    results = response.json()["results"]

    # At least one variant should match the selected ID.
    assert results

    # Verify that every returned variant has the requested identifier.
    assert all(v["id"] == variant_id for v in results)


# =============================================================================
# Annotation filtering tests
# =============================================================================

@pytest.mark.parametrize(
    ("column", "parameter"),
    [
        # Filter variants using the VEP gene symbol annotation.
        ("csq_SYMBOL", "gene"),

        # Filter variants using the VEP transcript or feature annotation.
        ("csq_Feature", "feature"),

        # Filter variants using the VEP consequence annotation.
        ("csq_Consequence", "consequence"),

        # Filter variants using the VCF FILTER field.
        ('"filter"', "filter"),
    ],
)
def test_annotation_filters(client, column, parameter):
    """
    Test the API filters associated with variant annotations.

    pytest.mark.parametrize executes this test once for each pair of:
      - database column
      - corresponding API query parameter

    The test dynamically retrieves an existing annotation value from
    the database, then uses this value to query the API.

    This approach ensures that the test uses values actually present
    in the synthetic dataset.

    Note:
        VEP consequence annotations can contain several terms separated
        by '&', for example:
        missense_variant&splice_region_variant

        The API supports filtering by individual consequence terms.
        Therefore, only the first term is used in this test.
    """

    # Retrieve an existing non-null and non-empty annotation value.
    #
    # The column name comes from the fixed parametrization above.
    # The query parameter is used later in the HTTP request.
    value = get_db_value(
        f"""
        SELECT {column}
        FROM variants
        WHERE {column} IS NOT NULL AND {column} != ''
        LIMIT 1
        """
    )

    # Skip the test if the selected annotation column does not contain
    # any usable value in the synthetic database.
    if value is None:
        pytest.skip(f"No usable value found for {column}.")

    # VEP consequences may contain multiple terms separated by '&'.
    # Extract the first consequence term to test individual-term filtering.
    if parameter == "consequence":
        value = value.split("&")[0]

    # Send a request using the corresponding API query parameter.
    #
    # Examples:
    #   /variants?gene=GENE1
    #   /variants?feature=ENST00000123456
    #   /variants?consequence=missense_variant
    #   /variants?filter=PASS
    response = client.get(
        "/variants",
        params={parameter: value},
    )

    # Ensure that the API request was successful.
    assert response.status_code == 200

    # The count field must match the actual number of returned results.
    assert response.json()["count"] == len(response.json()["results"])


# =============================================================================
# gnomAD boolean filtering tests
# =============================================================================

@pytest.mark.parametrize(
    "parameter",
    [
        # Select variants not covered by gnomAD.
        "notCoveredByGnomad",

        # Select variants present in gnomAD.
        "inGnomad",

        # Select variants passing the gnomAD-related filtering criteria.
        "passGnomad",
    ],
)
def test_gnomad_boolean_filters(client, parameter):
    """
    Test the boolean filters related to gnomAD annotations.

    Each API parameter is tested with both possible boolean values:
      - true
      - false

    This verifies that the API correctly accepts and processes
    both positive and negative boolean filters.

    The test checks the HTTP response and consistency of the returned
    count, but does not independently validate the biological meaning
    of each gnomAD annotation.
    """

    # Test both possible values for the selected boolean parameter.
    for value in ("true", "false"):

        # Send the request with the current boolean value.
        response = client.get(
            "/variants",
            params={parameter: value},
        )

        # Ensure that the API request was successful.
        assert response.status_code == 200

        # Convert the JSON response into a Python dictionary.
        data = response.json()

        # Verify consistency between the reported count and returned rows.
        assert data["count"] == len(data["results"])


