def test_filter_by_ac_an_af(client):
    """
    Test numeric filtering using allele count and allele frequency.

    The API supports:
      - ac_min: minimum alternate allele count
      - an_min: minimum total allele number
      - af_min: minimum alternate allele frequency
      - af_max: maximum alternate allele frequency

    The selected ranges are deliberately broad:
      - AC >= 0
      - AN >= 0
      - 0 <= AF <= 1

    These values should be valid for standard allele count and frequency
    data and should allow the API to return matching variants.

    This test primarily checks that numeric parameters are accepted
    and correctly processed by the API.
    """

    # Request variants satisfying the specified numeric constraints.
    response = client.get(
        "/variants",
        params={
            "ac_min": 0,
            "an_min": 0,
            "af_min": 0,
            "af_max": 1,
        },
    )

    # Ensure that the API request was successful.
    assert response.status_code == 200

    # Verify consistency between the reported count and returned rows.
    assert response.json()["count"] == len(response.json()["results"])


# =============================================================================
# Pagination tests
# =============================================================================

def test_pagination(client):
    """
    Test the pagination mechanism of the /variants endpoint.

    The API supports:
      - limit: maximum number of variants returned per request
      - offset: number of variants to skip before returning results

    This test retrieves two consecutive pages:
      - First page: variants 1 to 10.
      - Second page: variants 11 to 20.

    It checks that:
      1. Both requests are successful.
      2. Both pages contain exactly 10 variants.
      3. No variant is returned in both pages.

    Note:
        The test assumes that the API uses a deterministic ordering
        when retrieving variants. Without a stable ORDER BY clause,
        pagination can potentially return inconsistent results.
    """

    # Retrieve the first page of 10 variants.
    first = client.get(
        "/variants",
        params={"limit": 10, "offset": 0},
    )

    # Retrieve the second page of 10 variants.
    second = client.get(
        "/variants",
        params={"limit": 10, "offset": 10},
    )

    # Ensure that both API requests were successful.
    assert first.status_code == 200
    assert second.status_code == 200

    # Extract the variants returned by each page.
    first_results = first.json()["results"]
    second_results = second.json()["results"]

    # Each page should contain exactly 10 variants.
    assert len(first_results) == 10
    assert len(second_results) == 10

    # Define a composite key to identify a variant independently
    # of its annotations.
    #
    # Here, the key uses:
    #   chromosome, position, reference allele and alternate allele.
    key = lambda v: (v["chrom"], v["pos"], v["ref"], v["alt"])

    # Build sets of variant keys for both pages.
    # Sets make it possible to efficiently check for intersections.
    first_keys = {key(v) for v in first_results}
    second_keys = {key(v) for v in second_results}

    # The two pages must not contain any common variants.
    assert first_keys.isdisjoint(second_keys)


# =============================================================================
# Empty result tests
# =============================================================================

def test_no_matching_variant(client):
    """
    Test the API behavior when a filter does not match any variant.

    An intentionally invalid gene symbol is used to ensure that
    no corresponding variant exists in the synthetic database.

    The expected behavior is:
      - HTTP status code: 200
      - count: 0
      - results: empty list

    An empty result is a valid API response and should not generate
    an HTTP error.
    """

    # Request variants associated with a gene that should not exist.
    response = client.get(
        "/variants",
        params={"gene": "__NO_SUCH_GENE__"},
    )

    # A valid request with no matching results should still return HTTP 200.
    assert response.status_code == 200

    # The API should report zero matching variants.
    assert response.json()["count"] == 0

    # The results field should contain an empty list.
    assert response.json()["results"] == []


# =============================================================================
# Input validation tests
# =============================================================================

def test_invalid_coordinate_range(client):
    """
    Test coordinate range validation.

    The API should reject requests where the start position is greater
    than the end position.

    Such a genomic interval is invalid because the minimum coordinate
    cannot be greater than the maximum coordinate.

    FastAPI should return HTTP 422 (Unprocessable Entity) for this
    invalid request.
    """

    # Request an invalid genomic interval:
    # start = 100000 is greater than end = 100.
    response = client.get(
        "/variants",
        params={
            "chrom": "chr1",
            "start": 100000,
            "end": 100,
        },
    )

    # Verify that the API correctly rejects the invalid coordinate range.
    assert response.status_code == 422


def test_invalid_frequency_range(client):
    """
    Test allele frequency range validation.

    The API should reject requests where the minimum allele frequency
    is greater than the maximum allele frequency.

    For example:
      - af_min = 0.8
      - af_max = 0.2

    This range is mathematically invalid and should be rejected
    by the API with HTTP 422 (Unprocessable Entity).
    """

    # Request an invalid allele frequency interval.
    response = client.get(
        "/variants",
        params={
            "af_min": 0.8,
            "af_max": 0.2,
        },
    )

    # Verify that the API rejects the invalid frequency range.
    assert response.status_code == 422


def test_limit_cannot_exceed_500(client):
    """
    Test the maximum pagination limit.

    The API imposes a maximum limit of 500 variants per request
    to prevent excessively large responses.

    Requests exceeding this limit should be rejected.

    FastAPI should return HTTP 422 (Unprocessable Entity) because
    the supplied query parameter violates the API validation rules.
    """

    # Request 501 variants, exceeding the maximum allowed limit of 500.
    response = client.get(
        "/variants",
        params={"limit": 501},
    )

    # Verify that the API correctly rejects the excessive limit.
    assert response.status_code == 422
